%[text] ## Panneling
msb = 2;nsb=5;
s.Avg = subplot(2,5,[2,3,4]); %[output:38bec072]
s.con(1) = subplot(2,5,1); %[output:38bec072]
s.con(2) = subplot(2,5,6); %[output:38bec072]
s.con(3) = subplot(2,5,7); %[output:38bec072]
s.con(4) = subplot(2,5,8); %[output:38bec072]
s.con(5) = subplot(2,5,9); %[output:38bec072]
s.con(6) = subplot(2,5,10); %[output:38bec072]
s.con(7) = subplot(2,5,5); %[output:38bec072]
f=gcf;
f.Position = [0 0 800 500]; %[output:38bec072] %[output:592d09c7]
%%
%[text] ## Average Pannel
V = map.vm*1000;
% xrng = (0:xyxyr(5)) +xyxyr(-1 + iph*2);
xrng = (0:r) + xyT{iCr,1}(1);
yrng = (0:r) + xyT{iCr,1}(2);
Gfcs = map.Gfinal0T(xrng,yrng,:);
f.CurrentAxes = s.Avg;
gfcs = squeeze(mean(mean(Gfcs)))*10;%multiplication is no mean. just reduce the size of ticks
area(V,gfcs,FaceColor=[0.231 0.667 0.196]) %[control:colorPicker:4cb8]{"position":[23,42]} %[output:5c8a8b89]
xlim([-760 760]); %[output:5c8a8b89]
ylim([0 1.1]) %[output:5c8a8b89]
s.Avg.Clipping ="off";
xline(vFcs,'w:',LineWidth=2) %[output:5c8a8b89]
hold on %[output:5c8a8b89]
plot(V,gfcs,'k',LineWidth=2.5) %[output:5c8a8b89]
hold off %[output:5c8a8b89]
xlabel(labeler('E','meV')); %[output:5c8a8b89]
ylabel(labeler('LDOS','a.u')); %[output:5c8a8b89]
center_preserve_resizeAx(s.Avg,[.9 1.2]);
s.Avg.Position = s.Avg.Position + [0.02 0 0 0];
insert_pindx(s.Avg,"a") %[output:5c8a8b89]
