%[text] ## Fcns





% Triangle Test

% Create Transformation Matrix
% xl = s.Avg.XLim
% yl = s.Avg.YLim
% xywh = s.Avg.Position
% 
% p1p2p3_A = [xl([1 1 2]);yl([1 2 2]);1 1 1] %p1:Top left p2: Bottom left p3: Bottom right
% p1p2p3_F = [((xywh([1 2]))'*[1 1 1] +[xywh(3) 0 0;0 0 xywh(4)]); 1 1 1]% p1p2p3_F = %It is normalized figure frame
% I_A__F = p1p2p3_A*inv(p1p2p3_F)

function sqaxResz(ax,r)
ax.Position = sqResz(ax.Position,r);
end

function xywh_new = sqResz(xywh_old,r)
wh_old = xywh_old([3,4]);
wh_new = wh_old*r;
xy_new = xywh_old([1,2])- (1/2)*(r-1)*wh_old;
xywh_new = [xy_new wh_new];
end

function center_preserve_resizeAx(ax,rr)
xywh_old = ax.Position;
xywh_new = center_preserve_resize(xywh_old,rr);
ax.Position = xywh_new;
% ax.Position = center_preserve_resize(ax.Position,rr)
end

function xywh_new = center_preserve_resize(xywh_old,rr)
wh_old = xywh_old([3,4]);
wh_new = wh_old.*rr;
xy_new = xywh_old([1,2])- (1/2)*(rr-1).*wh_old;
xywh_new = [xy_new wh_new];
end

function draw_tri(ax1,ax2,p1,isBottom)
%define 3 points
p1_ax1 = p1;
xywh = ax2.Position;
pAx2BL_ax2f = xywh([1 2]);
pAx2BR_ax2f = xywh([1 2]) + [xywh(3) 0];
if ~isBottom
    pAx2BL_ax2f = pAx2BL_ax2f + [0 xywh(4)];
    pAx2BR_ax2f = pAx2BR_ax2f + [0 xywh(4)];
end
pAx2BL_ax1 = figToAxesCoord(ax1, pAx2BL_ax2f);
pAx2BR_ax1 = figToAxesCoord(ax1, pAx2BR_ax2f);
tri_ax1 = [p1_ax1' pAx2BL_ax1' pAx2BR_ax1'];

%drawtri_ax
f = gcf();
f.CurrentAxes = ax1;
draw_triax(tri_ax1(1,:),tri_ax1(2,:));
end

function draw_triax(vertices_x,vertices_y)
hold on
patch(vertices_x, vertices_y, 'k', 'FaceAlpha', 0.2,   'Clipping', 'off','EdgeColor','none')
hold off
end

function resizeAxesToSquare(ax)
    % Validate input
    if nargin < 1 || ~isgraphics(ax, 'axes')
        error('Input must be a valid axes handle.');
    end

    % Get current axes position
    originalUnits = ax.Units;
    ax.Units = 'pixels';
    axPosition = ax.Position;

    % Determine the minimum dimension
    minDimension = min(axPosition(3:4));

    % Calculate new position to maintain center alignment
    newX = axPosition(1) + (axPosition(3) - minDimension) / 2;
    newY = axPosition(2) + (axPosition(4) - minDimension) / 2;

    % Set new position
    ax.Position = [newX, newY, minDimension, minDimension];

    % Restore original units
    ax.Units = originalUnits;
end

function insert_valtage(ax,V)
str = string(V)+"mV";
xywh = ax.Position;
annotation("textbox",xywh, ...
    "EdgeColor","none", ...
    "String",str, ...
    "HorizontalAlignment","right", ...
    "VerticalAlignment","top", ...
    "Color",[1 1 1]*.3);
end

function insert_pindx(ax,str)
xywh = ax.Position;
annotation("textbox",xywh, ...
    "EdgeColor","none", ...
    "String",str, ...
    "HorizontalAlignment","left", ...
    "VerticalAlignment","cap", ...
    "Color",[1 1 1]*.0,...
    FontSize=15,...
    FontWeight="bold");
end

